-- name: by_schema
-- dialect: teradata
LOCKING ROW FOR ACCESS
SELECT TRIM(t.DatabaseName) AS schema_name, TRIM(t.TableName) AS view_name, CASE WHEN t.RequestTxtOverflow IS NOT NULL AND tt.RequestText IS NOT NULL THEN tt.RequestText ELSE t.RequestText END AS definition, COALESCE(tt.LineNo, 1) AS line_no, CASE WHEN t.RequestTxtOverflow IS NOT NULL THEN 1 ELSE 0 END AS has_overflow, t.CommentString AS comment FROM DBC.TablesV t LEFT JOIN DBC.TableTextV tt ON UPPER(TRIM(t.DatabaseName)) = UPPER(TRIM(tt.DatabaseName)) AND UPPER(TRIM(t.TableName)) = UPPER(TRIM(tt.TableName)) AND TRIM(tt.TableKind) = 'V' AND t.RequestTxtOverflow IS NOT NULL WHERE UPPER(TRIM(t.DatabaseName)) = UPPER(TRIM(COALESCE(:schema_name, DATABASE))) AND UPPER(TRIM(t.DatabaseName)) NOT IN ('DBC', 'SYSUDTLIB', 'SYSLIB', 'TD_SYSFNLIB', 'SYSSPATIAL', 'SYSBAR', 'LOCKLOGSHREDDER', 'SQLJ', 'TDSTATS', 'TD_SERVER_DB', 'CRASHDUMPS') AND TRIM(t.TableKind) = 'V' ORDER BY TRIM(t.DatabaseName), TRIM(t.TableName), COALESCE(tt.LineNo, 1);
